const e="pcg-impact-national-talent-expo",d=2025,t="Built from the 2025 NTE Rules and Guidelines. The manual prints no finals dates, venue, address, prizes, placings or points; those stay empty. The entry deadline of 1 May and late deadline of 15 May carry no year in the manual. The manual's sample score sheet and sample information pages (examples with a model name) are not copied. Category rules for Exhibit-size and equipment are captured as printed.",n={Title:"Rules & Criteria",Subtitle:"Impact PCG Student Ministries National Teen Talent Expo (NTE) - district and finals rules, 2025 edition",NoticeTitle:"Please Read Before Registering",Notice:"Read the official rules before you register. By signing a district or national registration form, pastors, leaders, parents and students agree to the rules and accept the decisions of the Director and judges as final. Only entries with a Christian message or theme are allowed. Entry deadline: {{FinalDeadline}}; early fee until {{EarlyDeadline}}.",Notes:["Age is the age on {{AgeDate}} of the National Finals year.","Only one entry per person per category at district level.","No entries are accepted after {{FinalDeadline}}. There are no refunds for cancellations.","Music for performances must be uploaded as MP3 files with the online entry form. No late audio files are accepted."],Sections:[{Key:"general",Title:"General rules",Items:["All participants must read and follow the official NTE rules. No other person is responsible for a participant's lack of information.","The NTE rules are the official rules for all district competitions.","All questions about the rules must come through the participant's district youth department.","Participants may not change their entry between the district Talent Expo and the National Talent Expo, except as the category rules allow or as the District Youth Director decides.","A rule violation of any kind, general or category, brings one overall deduction of 15 points. A time violation also brings one overall deduction of 15 points.","Each participant has 2 minutes to set up and 90 seconds to tear down. Christian Band has 4 minutes to set up and 2 minutes to tear down.","A participant in the national finals may be disqualified for not appearing at the set time and place for the performance.","Participants must be present, or send a representative, at the orientation meeting to complete the check-in forms and attend category meetings. A participant in more than one category may send a representative to each orientation, and a group may send one person for the whole group.","At orientation, performers hand their original soundtrack and any required outlines to the Category Chairman at roll call. Entrants in non-performing categories check in with their Category Chairman, who tells them where to place the exhibit. Bringing a back-up music file is encouraged.","Contestants may use only instruments on the approved instrument list, or they are disqualified.","The keyboard provided is set to grand piano. Its sounds and settings cannot be changed and transposing is not allowed.","All performances get the same theatre lighting. Special colours or lighting cues cannot be requested; lights are only on or off.","Microphones are set by an official sound technician before the Expo. Participants cannot ask for special sound settings.","Equipment provided at the finals: 1 keyboard, 1 drum set, 5 direct boxes, 1 podium, 1 wireless speaking microphone, a video projection system and screen for slide shows, 5 wireless or lapel microphones for theatrical drama, 8 microphones for vocal ensemble and 1 microphone for vocal solo. This equipment is not guaranteed at district competitions.","The Expo's purposes are to develop abilities and talents for the glory of God, to encourage students to use their abilities in church ministries, to give evaluation data on performances, to help students grow in their personal relationship with God and to help students build friendships with their peers."]},{Key:"eligibility",Title:"Who can enter",Items:["Age is counted on {{AgeDate}} of the National Finals competition year.","Solo divisions: Primary (ages 5-8), Junior (ages 9-12) and Senior (ages 13-19).","Group divisions: Kid (ages 5-12) and Teen (ages 13-19).","For group entries only, a 12-year-old may move up to the Teen division with the group. That person must then enter the Senior division for all solo entries too.","Each participant must come through a district Talent Expo and attend a church of the Pentecostal Church of God (PCG), a church in fellowship with the PCG, or a youth group registered with the National Youth Department.","Participation is also open to the global constituents of the PCG. Entrants outside the USA do not need to take part in a district event to enter the NTE Finals.","Only one entry per person per category is allowed at district level.","Participation is limited to Christian music and themes. If it is unclear whether a presentation is Christian, the National Office advises choosing another one. No dark themes are allowed.","Presentations judged not Christian or not Christian-themed are disqualified at the discretion of the National Talent Expo committee.","Entries must respect decency, modesty and Christian values. The District Youth Director must know each performance and the appropriate appearance of each participant.","Contestant clothing must not compromise Christian ideals (not suggestive, vulgar or revealing).","Participants must follow copyright law for music, scripts and other works: get the copyright or written permission from the publisher or creator and credit the creator."]},{Key:"registration",Title:"How to register",Items:["Each qualifying entry must complete an NTE entry form online and pay the entry fee. One form and one fee for each entry.","Entry fee: {{EntryFee}}. Late fee: {{LateEntryFee}}. No entries are submitted or allowed after {{FinalDeadline}}.","Files required with the entry (music, writing, lyric sheets, slide shows, reel links) must be submitted with the online entry form by the {{EarlyDeadline}} registration deadline.","Audio for performances must be in MP3 format and uploaded during the online entry form. No late audio files are accepted.","The National Youth Office does not give refunds for cancellations."]},{Key:"fees",Title:"Entry fees",Items:["Entry fee: {{EntryFee}} before the early deadline. Late fee: {{LateEntryFee}}.","The fee is per entry. The National Youth Office does not give refunds."]},{Key:"levels",Title:"District and national levels",Items:["Every participant must come through a district Talent Expo, except global entries (outside the USA), which go straight to the NTE Finals.","Each USA district may send at most three entries per category to the National Talent Expo. If a qualifying winner cannot attend, the district may choose to send alternate entries.","Global constituents may send at most two entries per country per category (outside the USA) to the NTE."]},{Key:"conduct",Title:"Conduct and discipline",Items:["Participants must stay committed to the ministry and represent Christ in behaviour and actions.","A participant who shows disrespect for people or property anywhere in the city is disqualified and dismissed, and the parties involved pay for any damage.","Participants and their representatives (parents, youth pastors and others) must not approach the Media Booth or the judges' table. This counts as a rule infraction. Issues go to the NTE Category Chairman.","Entries must be presented tastefully, and students must avoid actions or language that may be offensive or inappropriate."]},{Key:"judging",Title:"Judging",Items:["Each contestant is judged in five areas (see the criteria of each category). Each area is worth 20 points, so the maximum is 100 points per judge.","Each contestant has 3 scoring judges (maximum 300 points) and 1 technical judge who watches for rule infractions.","Decisions of the Director and judges are final.","On the sample score sheet, each area is marked with comment bands: 17-20 Superior, 13-16 Excellent, 9-12 Good, 5-8 Average and 1-4 Work on this area.","Judges look for originality, preparation and ministry. Easier selections done well score better than difficult selections done poorly."]},{Key:"points",Title:"Points and penalties",Items:["One 15-point overall deduction is made for any general or category rule infraction.","One 15-point overall deduction is made for any time violation.","Maximum score is 100 per judge and 300 across three scoring judges."]},{Key:"teams",Title:"Group entries",Items:["Group categories are entered in the Kid division (ages 5-12) or the Teen division (ages 13-19).","In an emergency, a substitute for one person in a group is allowed. No additions are allowed, only substitutions."]},{Key:"reporting",Title:"Score sheets and results",Items:["At the NTE Finals, each contestant's score sheet is returned electronically to the email address on the registration form."]},{Key:"other",Title:"Other notes",Items:["A new feature of the 2025 manual: rule changes are marked in red in the original document.","Group categories also include Christian Band, Worship Team and Reels in the Teen division only."]}],Documents:[{Title:"NTE Rules and Guidelines 2025 (PDF)",Url:"https://storage2.snappages.site/9WZGRR/assets/files/2025-NTE-Rules-Guidelines.pdf"}]},i=[],o=[],a=JSON.parse(`[{"Title":"Art","Source":"Art and Dimensional Art rules","Sections":{"About":["Painting (oil, water) and sketching (pencil, chalk and similar)."],"TimeAndFormat":null,"Rules":["Entries are delivered and set up by the contestant at both district and national competitions. Entries cannot be shipped.","The contestant collects the entry after the Expo, or arranges for pickup. Impact PCG Student Ministries is not responsible for entries left behind.","Each participant takes full responsibility for the entry before, during and after the event and is liable for any damage.","Art is created by one person only. Group art is not allowed.","Entries must be created entirely by the participant, with an appropriate theme, since the close of the previous national competition.","The typed information page shows category, name, age, district, picture and the theme or title. Each entry is shown with a typed information page. Handwritten pages are not allowed."],"Allowed":null,"NotAllowed":null,"Judging":["Judges want originality and careful attention to detail. High points are given for neatness, cleanliness, uniformity and precision.","Pay attention to correct perspective, symmetry and colour contrast."],"Points":null,"Notes":["Art elements: colour, line, mass, space and texture.","Think carefully about the title and try to make the entry minister to the viewer."]},"Markdown":"## About this competition\\n- Painting (oil, water) and sketching (pencil, chalk and similar).\\n\\n## Rules\\n- Entries are delivered and set up by the contestant at both district and national competitions. Entries cannot be shipped.\\n- The contestant collects the entry after the Expo, or arranges for pickup. Impact PCG Student Ministries is not responsible for entries left behind.\\n- Each participant takes full responsibility for the entry before, during and after the event and is liable for any damage.\\n- Art is created by one person only. Group art is not allowed.\\n- Entries must be created entirely by the participant, with an appropriate theme, since the close of the previous national competition.\\n- The typed information page shows category, name, age, district, picture and the theme or title. Each entry is shown with a typed information page. Handwritten pages are not allowed.\\n\\n## Judging\\n- Judges want originality and careful attention to detail. High points are given for neatness, cleanliness, uniformity and precision.\\n- Pay attention to correct perspective, symmetry and colour contrast.\\n\\n## Notes for participants\\n- Art elements: colour, line, mass, space and texture.\\n- Think carefully about the title and try to make the entry minister to the viewer."},{"Title":"Dimensional Art","Source":"Art and Dimensional Art rules","Sections":{"About":["Wood, metal, ceramic and similar materials."],"TimeAndFormat":null,"Rules":["Entries are delivered and set up by the contestant at both district and national competitions. Entries cannot be shipped.","The contestant collects the entry after the Expo, or arranges for pickup. Impact PCG Student Ministries is not responsible for entries left behind.","Each participant takes full responsibility for the entry before, during and after the event and is liable for any damage.","Dimensional Art entries are created by one person.","Entries must be created entirely by the participant, with an appropriate theme, since the close of the previous national competition.","The typed information page shows category, name, age, district, picture and the theme or title. Each entry is shown with a typed information page. Handwritten pages are not allowed."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["Art elements: colour, line, mass, space and texture."]},"Markdown":"## About this competition\\n- Wood, metal, ceramic and similar materials.\\n\\n## Rules\\n- Entries are delivered and set up by the contestant at both district and national competitions. Entries cannot be shipped.\\n- The contestant collects the entry after the Expo, or arranges for pickup. Impact PCG Student Ministries is not responsible for entries left behind.\\n- Each participant takes full responsibility for the entry before, during and after the event and is liable for any damage.\\n- Dimensional Art entries are created by one person.\\n- Entries must be created entirely by the participant, with an appropriate theme, since the close of the previous national competition.\\n- The typed information page shows category, name, age, district, picture and the theme or title. Each entry is shown with a typed information page. Handwritten pages are not allowed.\\n\\n## Notes for participants\\n- Art elements: colour, line, mass, space and texture."},{"Title":"Photography","Source":"Photography rules","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Entries are delivered and set up by the contestant at both district and national competitions. Entries cannot be shipped.","The contestant collects the entry after the Expo, or arranges for pickup. Impact PCG Student Ministries is not responsible for entries left behind.","Each participant takes full responsibility for the entry before, during and after the event and is liable for any damage.","The participant must photograph the entry. It needs an appropriate theme but does not have to be openly religious.","The photograph must be taken since the close of the previous national competition.","Entries must be exactly 8x10 inches.","The typed information page shows category, name, age, district, picture, theme or title, camera used, software (if any) and any other technology used."],"Allowed":["Black-and-white or colour photographs.","Computer improvements that enhance the original photograph (cropping, colour depth or hue, colour contrast and similar)."],"NotAllowed":["Typography added to the finished image. Words or letters must appear as part of the scene.","Collages."],"Judging":null,"Points":null,"Notes":["Do not over-edit. Most photography is best almost raw. Be specific with the theme and show the depth of what you capture."]},"Markdown":"## Rules\\n- Entries are delivered and set up by the contestant at both district and national competitions. Entries cannot be shipped.\\n- The contestant collects the entry after the Expo, or arranges for pickup. Impact PCG Student Ministries is not responsible for entries left behind.\\n- Each participant takes full responsibility for the entry before, during and after the event and is liable for any damage.\\n- The participant must photograph the entry. It needs an appropriate theme but does not have to be openly religious.\\n- The photograph must be taken since the close of the previous national competition.\\n- Entries must be exactly 8x10 inches.\\n- The typed information page shows category, name, age, district, picture, theme or title, camera used, software (if any) and any other technology used.\\n\\n## Allowed\\n- Black-and-white or colour photographs.\\n- Computer improvements that enhance the original photograph (cropping, colour depth or hue, colour contrast and similar).\\n\\n## Not allowed\\n- Typography added to the finished image. Words or letters must appear as part of the scene.\\n- Collages.\\n\\n## Notes for participants\\n- Do not over-edit. Most photography is best almost raw. Be specific with the theme and show the depth of what you capture."},{"Title":"Graphic Design","Source":"Graphic Design rules","Sections":{"About":["Senior division only. Accepted types: advertisement, business card, newsletter, poster, billboard, brochure, web page and logo."],"TimeAndFormat":null,"Rules":["Entries are delivered and set up by the contestant at both district and national competitions. Entries cannot be shipped.","The contestant collects the entry after the Expo, or arranges for pickup. Impact PCG Student Ministries is not responsible for entries left behind.","Each participant takes full responsibility for the entry before, during and after the event and is liable for any damage.","Entries must be printed at high resolution (at least 300 dpi) and put on display.","Size: no smaller than 8 by 10 inches and no larger than 24 by 24 inches. Students should submit the best representation of the design.","The typed information page shows category, name, picture, theme, software or program used and any other technology used.","Internet photos (such as stock photos) may be used if they are not copyrighted or the participant has permission and notes it on the cover sheet."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Senior division only. Accepted types: advertisement, business card, newsletter, poster, billboard, brochure, web page and logo.\\n\\n## Rules\\n- Entries are delivered and set up by the contestant at both district and national competitions. Entries cannot be shipped.\\n- The contestant collects the entry after the Expo, or arranges for pickup. Impact PCG Student Ministries is not responsible for entries left behind.\\n- Each participant takes full responsibility for the entry before, during and after the event and is liable for any damage.\\n- Entries must be printed at high resolution (at least 300 dpi) and put on display.\\n- Size: no smaller than 8 by 10 inches and no larger than 24 by 24 inches. Students should submit the best representation of the design.\\n- The typed information page shows category, name, picture, theme, software or program used and any other technology used.\\n- Internet photos (such as stock photos) may be used if they are not copyrighted or the participant has permission and notes it on the cover sheet."},{"Title":"Poetry","Source":"Creative Writing rules","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Poetry must be 12 to 20 lines and have a Christian theme.","The manuscript begins with a title page showing title, category, word count, name, picture, age and district.","Entries are typed (at least 12 pt font) and submitted digitally as a PDF only. These entries are pre-judged.","Submit with the entry form by the {{EarlyDeadline}} deadline. Each manuscript becomes the property of the National Youth Ministries office and is not returned.","A participant may write in both Poetry and Short Story."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["Read the judging sheets before writing. Judges look for original and imaginative work that is still believable. Make each word count.","Read the entry aloud, check spelling and grammar, and ask someone you trust to read it."]},"Markdown":"## Rules\\n- Poetry must be 12 to 20 lines and have a Christian theme.\\n- The manuscript begins with a title page showing title, category, word count, name, picture, age and district.\\n- Entries are typed (at least 12 pt font) and submitted digitally as a PDF only. These entries are pre-judged.\\n- Submit with the entry form by the {{EarlyDeadline}} deadline. Each manuscript becomes the property of the National Youth Ministries office and is not returned.\\n- A participant may write in both Poetry and Short Story.\\n\\n## Notes for participants\\n- Read the judging sheets before writing. Judges look for original and imaginative work that is still believable. Make each word count.\\n- Read the entry aloud, check spelling and grammar, and ask someone you trust to read it."},{"Title":"Short Story","Source":"Creative Writing rules","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Short Story may be fiction or non-fiction. It must have a Christian theme and be 500 to 1250 words.","The manuscript begins with a title page showing title, category, word count, name, picture, age and district.","Entries are typed (at least 12 pt font) and submitted digitally as a PDF only. These entries are pre-judged.","Submit with the entry form by the {{EarlyDeadline}} deadline. Each manuscript becomes the property of the National Youth Ministries office and is not returned."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["Begin with a strong opening and end with a strong closing statement. Use quotes sparingly."]},"Markdown":"## Rules\\n- Short Story may be fiction or non-fiction. It must have a Christian theme and be 500 to 1250 words.\\n- The manuscript begins with a title page showing title, category, word count, name, picture, age and district.\\n- Entries are typed (at least 12 pt font) and submitted digitally as a PDF only. These entries are pre-judged.\\n- Submit with the entry form by the {{EarlyDeadline}} deadline. Each manuscript becomes the property of the National Youth Ministries office and is not returned.\\n\\n## Notes for participants\\n- Begin with a strong opening and end with a strong closing statement. Use quotes sparingly."},{"Title":"Song Writing","Source":"Creative Writing rules - Songwriting","Sections":{"About":["Senior division only."],"TimeAndFormat":null,"Rules":["The music and the lyrics must be original and the theme Christian.","The song must not exceed 5 minutes.","No more than two song writers.","Submit an MP3 of the song with musical accompaniment and the lyrics as a PDF with the entry form by the {{EarlyDeadline}} deadline. Production and performance quality are not judged.","The lyric sheet begins with a title page showing title, category, name, picture, age and district.","Impact PCG Student Ministries is not responsible for the copyright of songs. By submitting, the contestant agrees to release the copyright for the purpose of the Talent Expo only. Contestants are advised to copyright their songs before public release."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Senior division only.\\n\\n## Rules\\n- The music and the lyrics must be original and the theme Christian.\\n- The song must not exceed 5 minutes.\\n- No more than two song writers.\\n- Submit an MP3 of the song with musical accompaniment and the lyrics as a PDF with the entry form by the {{EarlyDeadline}} deadline. Production and performance quality are not judged.\\n- The lyric sheet begins with a title page showing title, category, name, picture, age and district.\\n- Impact PCG Student Ministries is not responsible for the copyright of songs. By submitting, the contestant agrees to release the copyright for the purpose of the Talent Expo only. Contestants are advised to copyright their songs before public release."},{"Title":"Mime","Source":"Drama rules - Mime","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Time limit: 7 minutes.","Solo entries are limited to 1 participant. Group entries have 2 to 20 people.","An accompanying track is required.","In an emergency, one person in a group may be substituted. No additions."],"Allowed":null,"NotAllowed":["Costumes.","Speaking parts.","Props.","Anything that leaves residue on the stage (aerosols, pyrotechnics, confetti, liquids, fog machines, breakable items)."],"Judging":null,"Points":null,"Notes":["Mime entries are encouraged to use traditional mime clothes: white face paint, white gloves and black clothes.","Original pieces are encouraged. The main aim is ministry, not only entertainment."]},"Markdown":"## Rules\\n- Time limit: 7 minutes.\\n- Solo entries are limited to 1 participant. Group entries have 2 to 20 people.\\n- An accompanying track is required.\\n- In an emergency, one person in a group may be substituted. No additions.\\n\\n## Not allowed\\n- Costumes.\\n- Speaking parts.\\n- Props.\\n- Anything that leaves residue on the stage (aerosols, pyrotechnics, confetti, liquids, fog machines, breakable items).\\n\\n## Notes for participants\\n- Mime entries are encouraged to use traditional mime clothes: white face paint, white gloves and black clothes.\\n- Original pieces are encouraged. The main aim is ministry, not only entertainment."},{"Title":"Spoken Word","Source":"Drama rules - Spoken Word","Sections":{"About":["Senior division only. Spoken Word is the art and ministry of communicating poetry composed for presentation to an audience."],"TimeAndFormat":null,"Rules":["Spoken word pieces must be original and composed by an eligible NTE participant.","Time limit: 3 minutes.","The whole piece must be memorised."],"Allowed":["An instrumental backing track."],"NotAllowed":["Live music, extra media, or a backing track with words.","Costumes or props.","Anything that leaves residue on the stage."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Senior division only. Spoken Word is the art and ministry of communicating poetry composed for presentation to an audience.\\n\\n## Rules\\n- Spoken word pieces must be original and composed by an eligible NTE participant.\\n- Time limit: 3 minutes.\\n- The whole piece must be memorised.\\n\\n## Allowed\\n- An instrumental backing track.\\n\\n## Not allowed\\n- Live music, extra media, or a backing track with words.\\n- Costumes or props.\\n- Anything that leaves residue on the stage."},{"Title":"Theatrical Drama","Source":"Drama rules - Theatrical Drama","Sections":{"About":["Teen group division only."],"TimeAndFormat":null,"Rules":["Time limit: 5 minutes.","Maximum 10 performers, and only 5 may have a microphone.","Only hand-held props carried on and off stage by individual participants.","In an emergency, one person may be substituted. No additions."],"Allowed":null,"NotAllowed":["Any audio sound device during the performance.","Anything that leaves residue on the stage."],"Judging":null,"Points":null,"Notes":["Theatrics suits acting out parts of written scripts or short original scripts, such as Biblical characters or scenes. The key word is believability."]},"Markdown":"## About this competition\\n- Teen group division only.\\n\\n## Rules\\n- Time limit: 5 minutes.\\n- Maximum 10 performers, and only 5 may have a microphone.\\n- Only hand-held props carried on and off stage by individual participants.\\n- In an emergency, one person may be substituted. No additions.\\n\\n## Not allowed\\n- Any audio sound device during the performance.\\n- Anything that leaves residue on the stage.\\n\\n## Notes for participants\\n- Theatrics suits acting out parts of written scripts or short original scripts, such as Biblical characters or scenes. The key word is believability."},{"Title":"Human Video","Source":"Drama rules - Human Video","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Time limit: 7 minutes.","Groups only: maximum 20 people. Solo entries are not allowed.","The music track must have words. Voice-overs may be present but may not completely replace the lyrics.","The technique of lip sync must be used in most of the presentation.","Only hand-held props carried on and off stage by individual participants.","In an emergency, one person may be substituted. No additions."],"Allowed":null,"NotAllowed":["Speaking parts.","Anything that leaves residue on the stage."],"Judging":null,"Points":null,"Notes":["Human video was meant to act out the message of a song."]},"Markdown":"## Rules\\n- Time limit: 7 minutes.\\n- Groups only: maximum 20 people. Solo entries are not allowed.\\n- The music track must have words. Voice-overs may be present but may not completely replace the lyrics.\\n- The technique of lip sync must be used in most of the presentation.\\n- Only hand-held props carried on and off stage by individual participants.\\n- In an emergency, one person may be substituted. No additions.\\n\\n## Not allowed\\n- Speaking parts.\\n- Anything that leaves residue on the stage.\\n\\n## Notes for participants\\n- Human video was meant to act out the message of a song."},{"Title":"Drums and Percussion","Source":"Drum and Percussion rules","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Each contestant has 5 minutes to perform a routine.","The category is for 1 to 8 performers.","Drum sticks and drum thrones are the only personal gear allowed, unless playing another percussion instrument.","An accompaniment track is allowed, but no other musicians on stage. Judges score the percussion solo; solo without a track is recommended.","A basic kit is provided: 2 rack toms, floor tom, kick drum, 1 ride, 2 crash cymbals and hi-hat. Brand, model, cymbals and hardware vary by location.","Extra accessories may be added. Drummers are encouraged to bring headphones or in-ear monitors."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["This is a drum and percussion category, so entries do not have to be only a traditional drum kit."]},"Markdown":"## Rules\\n- Each contestant has 5 minutes to perform a routine.\\n- The category is for 1 to 8 performers.\\n- Drum sticks and drum thrones are the only personal gear allowed, unless playing another percussion instrument.\\n- An accompaniment track is allowed, but no other musicians on stage. Judges score the percussion solo; solo without a track is recommended.\\n- A basic kit is provided: 2 rack toms, floor tom, kick drum, 1 ride, 2 crash cymbals and hi-hat. Brand, model, cymbals and hardware vary by location.\\n- Extra accessories may be added. Drummers are encouraged to bring headphones or in-ear monitors.\\n\\n## Notes for participants\\n- This is a drum and percussion category, so entries do not have to be only a traditional drum kit."},{"Title":"Instrumental Solo","Source":"Instrumental rules","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Christian music only, not more than 5 minutes.","Any original composition must be noted on a lyric sheet naming the author, handed to the Category Chairman at orientation.","An instrumental soundtrack may be used. No vocals or accompaniment is allowed."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["Interpretation is the personal touch the contestant brings; style is the distinctive manner of performing.","Phrasing is like sentences in speech. Aim for clear and full tone. Finger dexterity is part of judging."]},"Markdown":"## Rules\\n- Christian music only, not more than 5 minutes.\\n- Any original composition must be noted on a lyric sheet naming the author, handed to the Category Chairman at orientation.\\n- An instrumental soundtrack may be used. No vocals or accompaniment is allowed.\\n\\n## Notes for participants\\n- Interpretation is the personal touch the contestant brings; style is the distinctive manner of performing.\\n- Phrasing is like sentences in speech. Aim for clear and full tone. Finger dexterity is part of judging."},{"Title":"Interpretive Dance","Source":"Interpretive Dance rules","Sections":{"About":["Solo in the solo divisions and ensemble in the Kid and Teen group divisions. Interpretive dance interprets the meaning in music and depicts emotions or tells a story."],"TimeAndFormat":null,"Rules":["Christian music or themes only, not more than 5 minutes. Time starts at the first movement or music.","The music may or may not have words.","Group entries are limited to 15 people.","Choreography is based on and conveys the intended message of the piece.","The focus must be dance.","In an emergency, one person in a group may be substituted. No additions."],"Allowed":["Hand-held streamers, ribbons, banners or flags, if they do not become the focus at the cost of real dance technique."],"NotAllowed":["Other stage props.","Choreography or costumes that are suggestive, vulgar or revealing."],"Judging":null,"Points":null,"Notes":["Judges want creative, age-appropriate choreography, clean technique, stage presence, well-rehearsed numbers and a clean professional look."]},"Markdown":"## About this competition\\n- Solo in the solo divisions and ensemble in the Kid and Teen group divisions. Interpretive dance interprets the meaning in music and depicts emotions or tells a story.\\n\\n## Rules\\n- Christian music or themes only, not more than 5 minutes. Time starts at the first movement or music.\\n- The music may or may not have words.\\n- Group entries are limited to 15 people.\\n- Choreography is based on and conveys the intended message of the piece.\\n- The focus must be dance.\\n- In an emergency, one person in a group may be substituted. No additions.\\n\\n## Allowed\\n- Hand-held streamers, ribbons, banners or flags, if they do not become the focus at the cost of real dance technique.\\n\\n## Not allowed\\n- Other stage props.\\n- Choreography or costumes that are suggestive, vulgar or revealing.\\n\\n## Notes for participants\\n- Judges want creative, age-appropriate choreography, clean technique, stage presence, well-rehearsed numbers and a clean professional look."},{"Title":"Short Sermon","Source":"Public Speaking rules - Short Sermon","Sections":{"About":null,"TimeAndFormat":null,"Rules":["A short sermon is a spoken biblical message that includes a Scripture or passage.","One person only.","Not more than 5 minutes.","Entries must be original and sources must be cited.","Notes may be used.","Only a Bible, notes and a podium may be used. Small hand-held props and multimedia are allowed; props are what the speaker can carry by hand.","Slides must be in Microsoft PowerPoint and submitted with the entry form by the {{EarlyDeadline}} deadline."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["Build a good outline. Be relevant and document statistics. Be sure the message is scriptural."]},"Markdown":"## Rules\\n- A short sermon is a spoken biblical message that includes a Scripture or passage.\\n- One person only.\\n- Not more than 5 minutes.\\n- Entries must be original and sources must be cited.\\n- Notes may be used.\\n- Only a Bible, notes and a podium may be used. Small hand-held props and multimedia are allowed; props are what the speaker can carry by hand.\\n- Slides must be in Microsoft PowerPoint and submitted with the entry form by the {{EarlyDeadline}} deadline.\\n\\n## Notes for participants\\n- Build a good outline. Be relevant and document statistics. Be sure the message is scriptural."},{"Title":"Stand-up Comedy","Source":"Public Speaking rules - Christian Stand-up Comedy","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Solo entries are one person. Group entries are limited to 4 people.","Not more than 5 minutes.","Props are allowed but limited to what presenters can carry by hand into the presentation space.","Entries must be tasteful. Make it your goal to edify Jesus. Ask the District Youth Director if unsure."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Rules\\n- Solo entries are one person. Group entries are limited to 4 people.\\n- Not more than 5 minutes.\\n- Props are allowed but limited to what presenters can carry by hand into the presentation space.\\n- Entries must be tasteful. Make it your goal to edify Jesus. Ask the District Youth Director if unsure."},{"Title":"Vocal Solo","Source":"Vocal rules","Sections":{"About":["Female Solo and Male Solo are separate entries in each solo division."],"TimeAndFormat":null,"Rules":["Songs must not be longer than 5 minutes.","Accompaniment is optional. Only the vocal performance is judged.","If live music is used, accompaniment is limited to a single instrument.","In an emergency, one person in a group may be substituted. No additions."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["Make a unique selection. Choose music inside your vocal range. It is better to sing an easier song well than a hard one badly."]},"Markdown":"## About this competition\\n- Female Solo and Male Solo are separate entries in each solo division.\\n\\n## Rules\\n- Songs must not be longer than 5 minutes.\\n- Accompaniment is optional. Only the vocal performance is judged.\\n- If live music is used, accompaniment is limited to a single instrument.\\n- In an emergency, one person in a group may be substituted. No additions.\\n\\n## Notes for participants\\n- Make a unique selection. Choose music inside your vocal range. It is better to sing an easier song well than a hard one badly."},{"Title":"Vocal Ensemble","Source":"Vocal rules - Vocal Ensemble","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Songs must not be longer than 5 minutes.","Accompaniment is optional. Only the vocal performance is judged.","If live music is used, accompaniment is limited to a single instrument.","Background vocals are not allowed on vocal ensemble soundtracks.","In an emergency, one person in the group may be substituted. No additions."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Rules\\n- Songs must not be longer than 5 minutes.\\n- Accompaniment is optional. Only the vocal performance is judged.\\n- If live music is used, accompaniment is limited to a single instrument.\\n- Background vocals are not allowed on vocal ensemble soundtracks.\\n- In an emergency, one person in the group may be substituted. No additions."},{"Title":"Christian Rap","Source":"Vocal rules - Christian Rap","Sections":{"About":["Senior division only."],"TimeAndFormat":null,"Rules":["Songs must not be longer than 5 minutes.","Limited to one participant.","Most of the song must be rap.","Background vocals may be used for the chorus only.","Accompaniment is optional; if live music is used it is a single instrument."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["Rappers are judged mainly on lyricism and ability to move a crowd."]},"Markdown":"## About this competition\\n- Senior division only.\\n\\n## Rules\\n- Songs must not be longer than 5 minutes.\\n- Limited to one participant.\\n- Most of the song must be rap.\\n- Background vocals may be used for the chorus only.\\n- Accompaniment is optional; if live music is used it is a single instrument.\\n\\n## Notes for participants\\n- Rappers are judged mainly on lyricism and ability to move a crowd."},{"Title":"Christian Band","Source":"Christian Band rules","Sections":{"About":["Teen group division only."],"TimeAndFormat":null,"Rules":["Christian music only, not more than 5 minutes.","A band has 2 to 10 participants, all inside the age limits. Not every singer must play and not every player must sing.","Judging covers both singing and playing.","Any original songs are noted on a lyric sheet naming the author, handed in at orientation.","Set-up is 4 minutes and tear-down 2 minutes.","Tracks are limited to click/guide and pads only. In-ear monitors are not guaranteed.","In an emergency, one person may be substituted. No additions."],"Allowed":null,"NotAllowed":["Actions or language that may be offensive or inappropriate."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Teen group division only.\\n\\n## Rules\\n- Christian music only, not more than 5 minutes.\\n- A band has 2 to 10 participants, all inside the age limits. Not every singer must play and not every player must sing.\\n- Judging covers both singing and playing.\\n- Any original songs are noted on a lyric sheet naming the author, handed in at orientation.\\n- Set-up is 4 minutes and tear-down 2 minutes.\\n- Tracks are limited to click/guide and pads only. In-ear monitors are not guaranteed.\\n- In an emergency, one person may be substituted. No additions.\\n\\n## Not allowed\\n- Actions or language that may be offensive or inappropriate."},{"Title":"Worship Team","Source":"Christian Band rules - Worship Team","Sections":{"About":["Teen group division only. A Worship Team entry is the art of leading others in worship."],"TimeAndFormat":null,"Rules":["2 to 10 eligible participants.","Time limit: 5 minutes.","The team must have both vocalists and instrumentalists.","Tracks are limited to click/guide and pads only. In-ear monitors are not guaranteed.","In an emergency, one person may be substituted. No additions."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["The goal is to lead the room into worship. A team may play a set of songs or one song; a set should be thematic."]},"Markdown":"## About this competition\\n- Teen group division only. A Worship Team entry is the art of leading others in worship.\\n\\n## Rules\\n- 2 to 10 eligible participants.\\n- Time limit: 5 minutes.\\n- The team must have both vocalists and instrumentalists.\\n- Tracks are limited to click/guide and pads only. In-ear monitors are not guaranteed.\\n- In an emergency, one person may be substituted. No additions.\\n\\n## Notes for participants\\n- The goal is to lead the room into worship. A team may play a set of songs or one song; a set should be thematic."},{"Title":"Reels","Source":"Short Film rules - Reels/Shorts","Sections":{"About":["Teen group division only."],"TimeAndFormat":null,"Rules":["A reel must not be longer than 60 seconds and must have a Christian theme.","Entries must be presented tastefully.","Directors and editors must be inside the age limits.","Entries must be the registrant's own original work.","Upload the reel to YouTube as a YouTube Short and submit the link with the entry form by the {{EarlyDeadline}} deadline.","Never use software, sound files, video, music or quotes without copyright or written permission, and never use unpublished music or scripts without the creator's written permission. Always credit the creator."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["The main aim is ministry, not only entertainment."]},"Markdown":"## About this competition\\n- Teen group division only.\\n\\n## Rules\\n- A reel must not be longer than 60 seconds and must have a Christian theme.\\n- Entries must be presented tastefully.\\n- Directors and editors must be inside the age limits.\\n- Entries must be the registrant's own original work.\\n- Upload the reel to YouTube as a YouTube Short and submit the link with the entry form by the {{EarlyDeadline}} deadline.\\n- Never use software, sound files, video, music or quotes without copyright or written permission, and never use unpublished music or scripts without the creator's written permission. Always credit the creator.\\n\\n## Notes for participants\\n- The main aim is ministry, not only entertainment."}]`),s=[],r=[{Key:"AgeDate",Kind:"date",Label:"Date on which age is counted",Value:"1 June of the National Finals competition year",Source:"General Rule 1"},{Key:"EarlyDeadline",Kind:"date",Label:"Early entry deadline (also deadline for entry files)",Value:"1 May",Source:"General Rule 7; category rules"},{Key:"FinalDeadline",Kind:"date",Label:"Last date for late entries",Value:"15 May",Source:"General Rule 7"},{Key:"EntryFee",Kind:"fee",Label:"Entry fee",Value:"USD 25 per entry before May 1",Source:"General Rule 7"},{Key:"LateEntryFee",Kind:"fee",Label:"Late entry fee",Value:"USD 50 per entry from May 1 to May 15",Source:"General Rule 7"},{Key:"OfficeContact",Kind:"contact",Label:"Contact for questions",Value:{Name:"Impact PCG Student Ministries office",Role:"National Youth Office",Phone:"817-554-5900 ext. 352",WhatsApp:"",Email:"impact@pcg.org"},Source:"Letter to participants"},{Key:"Website",Kind:"link",Label:"Organiser website for the latest updates",Value:"www.impactym.com",Source:"Letter to participants"},{Key:"SocialHandles",Kind:"text",Label:"Organiser social media",Value:"followtheimpact; @impactpcg; @impact_ym",Source:"Back cover"},{Key:"Announcements",Kind:"news",Label:"Notices printed in the manual",Value:[{Date:"",Title:"2025 manual",Text:"New rule changes are marked in red in the 2025 NTE Rules and Guidelines.",Url:"https://storage2.snappages.site/9WZGRR/assets/files/2025-NTE-Rules-Guidelines.pdf"}],Source:"Table of contents page"}],l=[{Claim:"Rules, eligibility, fees, deadlines, category rules and judging areas are taken from the organiser's own 2025 NTE Rules and Guidelines.",SourceType:"Primary - the event's own rules document",Source:"Impact PCG Student Ministries - NTE Rules and Guidelines 2025",Url:"https://storage2.snappages.site/9WZGRR/assets/files/2025-NTE-Rules-Guidelines.pdf"},{Claim:"The rules do not print event dates, a venue or address for the finals, or prizes; the Expo is held each year after district rounds in the fall.",SourceType:"Primary - the event's own rules document",Source:"Impact PCG Student Ministries - NTE Rules and Guidelines 2025",Url:"https://storage2.snappages.site/9WZGRR/assets/files/2025-NTE-Rules-Guidelines.pdf"}],u={TemplateKey:e,Year:2025,Note:t,Page:n,ParticipantTypes:i,AgeGroups:o,Competitions:a,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{o as AgeGroups,s as CompetitionAgeGroups,a as Competitions,l as Evidence,t as Note,n as Page,i as ParticipantTypes,e as TemplateKey,r as Variables,d as Year,u as default};
